def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division truncates toward zero, matching typical RPN calculator behavior.
    """
    stack = []
    for tok in tokens:
        if tok in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

