    """Run-length encode an iterable *s*.
    Returns a list of [item, count] pairs for each maximal run of equal consecutive items.
    If *s* is empty or not iterable, returns an empty list.
    """
    try:
        iterator = iter(s)
    except TypeError:
        return []
    try:
        prev = next(iterator)
    except StopIteration:
        return []
    count = 1
    res = []
    for item in iterator:
        if item == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = item
            count = 1
    res.append([prev, count])
    return res

