    Handles empty input and rejects non‑list/tuple inputs by returning 0.
    Uses O(n log n) patience sorting algorithm.
    """
    # Ensure the input is a sequence (list or tuple). Other types return 0.
    if not isinstance(nums, (list, tuple)):
        return 0
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # Only allow comparable elements; if comparison fails, treat as unextendable.
        try:
            i = bisect.bisect_left(tails, x)
