def solve(grid):
    """Count islands in a possibly ragged grid of 0/1.
    Connectivity is 4-directional (up, down, left, right).
    Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # four directions
            for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < len(grid[nx]):
                    if not visited[nx][ny] and grid[nx][ny] == 1:
                        stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    Handles empty list correctly.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find leftmost index where tails[idx] >= x
        idx = bisect.bisect_left(tails, x)
