def solve(grid):
    """Count islands of 1s in a grid.
    This implementation is defensive: it works even if the input grid is
    jagged (rows of differing lengths) or contains non‑int values. Any cell
    that is not exactly the integer ``1`` is treated as water.
    Cells are connected orthogonally (up, down, left, right).
    """
    if not grid:
        return 0
    # Determine number of rows
    rows = len(grid)
    # Prepare visited set of (r, c) tuples
    visited = set()
    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows:
                # each row may have its own length
                if 0 <= nc < len(grid[nr]):
                    yield nr, nc
    def dfs(start_r, start_c):
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == 1:
                    stack.append((nr, nc))
    islands = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r, c) not in visited:
                islands += 1
                dfs(r, c)
    return islands

